const STALE_JOB_TIMEOUT_MS: number = (() => {
  const env = process.env.IVX_WORKER_STALE_TIMEOUT_MS;
  const parsed = env ? Number.parseInt(env, 10) : NaN;
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 30 * 60 * 1000; // 30 min default
})();

