# GitHub installation token from .gitconfig
GH_TOKEN = "ghs_qcVm3JMWcdu15mSS1xxMw9xPrNXKPq1IlpLg"
OWNER = "ibb142"
REPO = "ivx-holdings-platform"

def gh_api(method, path, data=None):
    url = f"https://api.github.com/repos/{OWNER}/{REPO}{path}"
    headers = {
        'Accept': 'application/vnd.github+json',
        'Authorization': f'Bearer {GH_TOKEN}',
        'X-GitHub-Api-Version': '2022-11-28',
    }
    body = json.dumps(data).encode() if data else None
    if data:
        headers['Content-Type'] = 'application/json'
    req = urllib.request.Request(url, data=body, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        error_body = e.read().decode()
        return e.code, json.loads(error_body) if error_body else {}

# 1. Check if rate limit has reset - get main HEAD
