if status == 200:
    main_sha = main_data['commit']['sha']
    print(f"GitHub main HEAD: {main_sha[:12]}")

    # 2. Get ivx-autonomous HEAD
    status2, auto_data = gh_api('GET', '/branches/ivx-autonomous')
    if status2 == 200:
        auto_sha = auto_data['commit']['sha']
        print(f"GitHub ivx-autonomous HEAD: {auto_sha[:12]}")

        # 3. Compare branches
        status3, compare = gh_api('GET', f'/compare/{main_sha}...{auto_sha}')
        if status3 == 200:
            print(f"Commits ahead: {compare.get('ahead_by', 0)}")
            print(f"Commits behind: {compare.get('behind_by', 0)}")
            print(f"Status: {compare.get('status', 'unknown')}")

            # 4. Check for existing open PRs
            status4, prs = gh_api('GET', '/pulls?state=open&head=ibb142:ivx-autonomous&base=main')
            if status4 == 200:
                print(f"\nOpen PRs from ivx-autonomous: {len(prs)}")
                for pr in prs:
                    print(f"  PR #{pr['number']}: {pr['title'][:60]} — mergeable={pr.get('mergeable')}")

                if prs:
                    # Merge the existing PR
                    pr_number = prs[0]['number']
                    print(f"\n--- Merging PR #{pr_number} ---")
                    status5, merge_result = gh_api('PUT', f'/pulls/{pr_number}/merge', {
                        "merge_method": "squash",
                        "commit_title": f"fix: replace empty catch blocks with proper error logging across IVX IA pipeline (PR #{pr_number})"
                    })
                    print(f"Merge result: HTTP {status5}")
                    if status5 == 200:
                        print(f"  Merged: {merge_result.get('sha', '')[:12]}")
                        print(f"  Message: {merge_result.get('message', '')}")
                    else:
                        print(f"  Error: {json.dumps(merge_result)[:300]}")
                else:
                    # Create a new PR
                    print(f"\n--- Creating new PR ---")
                    status5, pr_result = gh_api('POST', '/pulls', {
                        "title": "fix: replace empty catch blocks with proper error logging across IVX IA pipeline",
                        "head": "ivx-autonomous",
                        "base": "main",
                        "body": "6 empty catch blocks replaced with proper error logging in 4 backend files. Fixes err:any type safety."
                    })
                    print(f"Create PR: HTTP {status5}")
                    if status5 == 201:
                        pr_number = pr_result['number']
                        print(f"  PR #{pr_number} created")

                        # Merge it immediately
                        print(f"\n--- Merging PR #{pr_number} ---")
                        status6, merge_result = gh_api('PUT', f'/pulls/{pr_number}/merge', {
                            "merge_method": "squash"
                        })
                        print(f"Merge: HTTP {status6}")
                        if status6 == 200:
                            print(f"  Merged: {merge_result.get('sha', '')[:12]}")
                        else:
                            print(f"  Error: {json.dumps(merge_result)[:300]}")
                    else:
                        print(f"  Error: {json.dumps(pr_result)[:400]}")
            else:
                print(f"PR list error: HTTP {status4}")
        else:
            print(f"Compare error: HTTP {status3}")
    else:
        print(f"ivx-autonomous error: HTTP {status2}")
else:
    print(f"main error: HTTP {status} — {json.dumps(main_data)[:200]}")
